// Shared logic for the 3 Early Retirement Request reviewer stages
// (Supervisor → District HOD → PS). Each stage's component supplies its
// own `stageConfig` (see the per-stage .vue files under
// lesotho/components/early-retirement/) and combines this mixin with
// generalMixin (for loggedInStaff) and processQuestionnaire (for the
// actual submit-to-backend call).
//
// ── Backend contract (ground truth: modules/workflows/EarlyRetirement/*.js) ──
// Each stage POSTs via processFHIR() to /fhir/QuestionnaireResponse with:
//   - questionnaire: this.stageConfig.questionnaireUrl (set per-component)
//   - flat body fields:
//       reviewDecision: "approved" | "rejected"   (review-status-codesystem)
//       comments: string
//       date: "YYYY-MM-DD"
//   - practitioner/request are carried as ?practitioner=&request= in the
//     query string (both the task link and processFHIR's querystring
//     passthrough carry them) — the workflows read req.query.practitioner
//     and req.query.request, NOT the request body, for those two.
//   NOTE: deliberately not named "status" — processFHIR() (processQuestionnaire
//   mixin, shared core code) always sets this.fhir.status = "completed" for
//   the FHIR QuestionnaireResponse's own resource status, which would
//   otherwise silently overwrite the review decision before it's POSTed.
//
// This mixin deliberately does NOT replicate the backend's authorization
// checks (e.g. "are you really the supervisor of this staff member") —
// those are enforced server-side and re-checked on every submit regardless
// of what this page shows. It only guards against clearly missing data
// (no request id) and gives a read-only view of where the request
// currently stands so reviewers aren't confused, per the workflow's own
// sequence enforcement (undersupervisorreview → underdistricthodreview →
// underpsreview).

const REQUEST_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/early-retirement-request-profile";
const REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/review-early-retirement-request-profile";

// Position-detail extension URLs — same ones position/view-staff-role.vue's
// loadRole()/enrichPosition() read off the staff member's current
// PractitionerRole and its linked position Basic, reused here to show the
// same read-only Position Details block to reviewers.
const POSITION_EXT = {
  POSITION: "http://ihris.org/fhir/StructureDefinition/position-reference",
  DESIGNATION: "http://ihris.org/fhir/StructureDefinition/designation",
  DEPARTMENT: "http://ihris.org/fhir/StructureDefinition/department",
  POS_NAME: "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
};

const STAGES = [
  {
    code: "supervisor",
    label: "Supervisor",
    expectedStatus: "undersupervisorreview",
    icon: "mdi-account-tie",
  },
  {
    code: "districthod",
    label: "District HOD",
    expectedStatus: "underdistricthodreview",
    icon: "mdi-account-star",
  },
  {
    code: "ps",
    label: "PS",
    expectedStatus: "underpsreview",
    icon: "mdi-shield-account",
  },
];

export default {
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,
      saving: false,
      formSubmitted: false,

      requestId: null,
      staffPractitionerRef: null,
      staffName: "",
      staffDob: null,
      // Age today, and age as of the requested retirement date — shown
      // separately since eligibility is judged on the latter, but a
      // reviewer needs both to make sense of the request.
      currentAge: null,
      staffAge: null,

      request: {
        reason: "",
        expectedRetirementDate: null,
        status: null,
        statusDisplay: "",
        eventDate: null,
      },
      reviews: [],

      // Read-only staff position details (current PractitionerRole), shown
      // alongside the request overview so reviewers can see the staff
      // member's designation/department/facility/district without leaving
      // the page. Left blank ("—" in the template) when the staff member
      // has no current role on file.
      position: {
        designation: "",
        department: "",
        facility: "",
        district: "",
      },

      form: {
        status: null,
        comments: "",
        date: new Date().toISOString().substr(0, 10),
      },

      afterSaveMessage: "",
      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    myExistingReview() {
      return (
        this.reviews.find(
          (r) => r.reviewerCode === this.stageConfig.reviewerCode,
        ) || null
      );
    },

    myTurn() {
      return (
        !this.myExistingReview &&
        this.request.status === this.stageConfig.expectedStatus
      );
    },

    currentStageLabel() {
      const stage = STAGES.find((s) => s.expectedStatus === this.request.status);
      if (stage) return stage.label;
      if (this.request.status === "psapproved") return "Approved";
      if (this.request.status === "psrejected") return "Rejected";
      return this.request.statusDisplay || "—";
    },

    // Always the full 3-stage pipeline, each paired with its review once
    // one exists — so the timeline renders in full from the moment a
    // request is submitted (e.g. the Supervisor stage, where `reviews` is
    // still empty because nobody has reviewed yet), not only once reviews
    // start arriving.
    timeline() {
      return STAGES.map((stage) => ({
        ...stage,
        review: this.reviews.find((r) => r.reviewerCode === stage.code) || null,
      }));
    },

    isPastMyStage() {
      const myIndex = STAGES.findIndex(
        (s) => s.code === this.stageConfig.reviewerCode,
      );
      const currentIndex = STAGES.findIndex(
        (s) => s.expectedStatus === this.request.status,
      );
      if (currentIndex === -1) return true; // terminal (psapproved/psrejected)
      return currentIndex > myIndex;
    },

    today() {
      return new Date().toISOString().substr(0, 10);
    },

    initials() {
      if (!this.staffName) return "?";
      return this.staffName
        .split(" ")
        .filter(Boolean)
        .slice(0, 2)
        .map((n) => n[0].toUpperCase())
        .join("");
    },
  },

  methods: {
    // Extension urls are keyed by the *Extension definition's* id, not the
    // FSH slice name — try every candidate given.
    getExt(resource, urlParts) {
      const candidates = Array.isArray(urlParts) ? urlParts : [urlParts];
      const exts = resource.extension || [];
      for (const part of candidates) {
        const found = exts.find((e) => e.url.includes(part));
        if (found) return found;
      }
      return null;
    },

    refId(ref) {
      if (!ref) return null;
      return ref.includes("/") ? ref.split("/")[1] : ref;
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color: color || "success" };
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return "N/A";
      const day = String(date.getDate()).padStart(2, "0");
      const month = String(date.getMonth() + 1).padStart(2, "0");
      return `${day}/${month}/${date.getFullYear()}`;
    },

    // Age in whole years as of `atDate` (defaults to today) — purely
    // informational client-side context, mirroring the same
    // moment(...).diff(..., 'years') calculation earlyRetirementRequestWorkflow.js
    // does server-side, so what reviewers see here matches what actually
    // gets enforced when a request is submitted.
    calcAge(birthDate, atDate) {
      if (!birthDate) return null;
      const dob = new Date(birthDate);
      const at = atDate ? new Date(atDate) : new Date();
      if (isNaN(dob.getTime()) || isNaN(at.getTime())) return null;
      let age = at.getFullYear() - dob.getFullYear();
      const m = at.getMonth() - dob.getMonth();
      if (m < 0 || (m === 0 && at.getDate() < dob.getDate())) {
        age--;
      }
      return age;
    },

    statusKey(status) {
      if (!status) return "warn";
      if (status === "approved" || status === "psapproved") return "done";
      if (status === "rejected" || status === "psrejected") return "error";
      if (status && status.includes("review")) return "active";
      return "warn";
    },

    async loadRequest() {
      const response = await fetch(`/fhir/Basic/${this.requestId}`);
      if (!response.ok) throw new Error("Early retirement request not found");
      const resource = await response.json();
      if (!resource.meta?.profile?.includes(REQUEST_PROFILE)) {
        throw new Error("Resource is not an early retirement request");
      }

      const statusCoding = this.getExt(resource, "request-status")
        ?.valueCoding;

      this.request = {
        reason: this.getExt(resource, "reason")?.valueString || "",
        expectedRetirementDate: this.getExt(
          resource,
          "expected-retirement-date",
        )?.valueDate,
        status: statusCoding?.code || null,
        statusDisplay: statusCoding?.display || "Pending",
        eventDate: this.getExt(resource, "event-date")?.valueDateTime,
      };

      this.staffPractitionerRef =
        this.queries?.practitioner && "Practitioner/" + this.queries.practitioner ||
        this.getExt(resource, "ihris-practitioner-reference")?.valueReference
          ?.reference;
    },

    async loadPractitioner() {
      if (!this.staffPractitionerRef) return;
      try {
        const id = this.refId(this.staffPractitionerRef);
        const response = await fetch(`/fhir/Practitioner/${id}`);
        const practitioner = await response.json();
        const name = practitioner.name?.[0];
        this.staffName = name
          ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
          : "Unknown";
        this.staffDob = practitioner.birthDate || null;
        this.currentAge = this.calcAge(this.staffDob);
        this.staffAge = this.calcAge(
          this.staffDob,
          this.request.expectedRetirementDate,
        );
      } catch (error) {
        console.error("Error loading staff practitioner:", error);
        this.staffName = "Unknown";
      }
    },

    // No dedicated search param is wired up for
    // early-retirement-request-reference, so — same approach used
    // elsewhere in this codebase (see staff-exchange-view.vue) — reviews
    // are fetched by profile and matched client-side against this request.
    async loadReviews() {
      try {
        const res = await fetch(
          `/fhir/Basic?_profile=${REVIEW_PROFILE}&_count=200`,
        );
        const bundle = await res.json();
        const resources = (bundle.entry || []).map((e) => e.resource);
        const wanted = "Basic/" + this.requestId;

        const matches = resources.filter((r) => {
          const ref = this.getExt(r, "early-retirement-request-reference")
            ?.valueReference?.reference;
          return ref === wanted;
        });

        const reviewerRefs = [
          ...new Set(
            matches
              .map(
                (r) =>
                  this.getExt(r, "ihris-practitioner-reference")
                    ?.valueReference?.reference,
              )
              .filter(Boolean),
          ),
        ];
        const nameMap = {};
        await Promise.all(
          reviewerRefs.map(async (ref) => {
            try {
              const r = await fetch(`/fhir/${ref}?_elements=name`);
              const pract = await r.json();
              const name = pract.name?.[0];
              nameMap[ref] = name
                ? `${(name.given || []).join(" ")} ${name.family || ""}`.trim()
                : ref;
            } catch {
              nameMap[ref] = ref;
            }
          }),
        );

        this.reviews = matches.map((r) => {
          const reviewerRef = this.getExt(r, "ihris-practitioner-reference")
            ?.valueReference?.reference;
          const statusCoding = this.getExt(r, "review-status")?.valueCoding;
          return {
            id: r.id,
            reviewerCode: this.getExt(r, "reviewer")?.valueCoding?.code,
            reviewerLabel: this.getExt(r, "reviewer")?.valueCoding?.display,
            reviewerName: nameMap[reviewerRef] || "Unknown",
            status: statusCoding?.code || null,
            statusDisplay: statusCoding?.display || "Pending",
            comments: this.getExt(r, "comments")?.valueString || "",
            date: this.getExt(r, "review-date")?.valueDate,
          };
        });
      } catch (error) {
        console.error("Error loading reviews:", error);
      }
    },

    // Read-only Position Details for the staff member under review — the
    // staff's *current* PractitionerRole, fetched the same way
    // position/assign-staff-role.vue's own loadCurrentRole() does (via the
    // /site/general/getCurrentRole/<practitioner> backend helper), then
    // parsed the same way position/view-staff-role.vue's loadRole() /
    // enrichPosition() / loadFacilityHierarchy() do. Never throws — a
    // missing/inactive role just leaves `position` fields blank, which the
    // template renders as "—".
    async loadStaffPosition() {
      if (!this.staffPractitionerRef) return;
      try {
        const id = this.refId(this.staffPractitionerRef);
        const res = await fetch(`/site/general/getCurrentRole/${id}`);
        const role = await res.json();
        if (!role || !role.id) return;

        // Facility → council → district — location[0] is a native FHIR
        // field on the PractitionerRole itself, not an extension.
        const facilityRef = role.location?.[0]?.reference;
        if (facilityRef) {
          try {
            const facRes = await fetch(`/fhir/${facilityRef}`);
            const facData = await facRes.json();
            this.position.facility = facData.name || facilityRef;

            const councilRef = facData.partOf?.reference;
            if (councilRef) {
              const councilRes = await fetch(`/fhir/${councilRef}`);
              const councilData = await councilRes.json();
              const districtRef = councilData.partOf?.reference;
              if (districtRef) {
                const districtRes = await fetch(`/fhir/${districtRef}`);
                const districtData = await districtRes.json();
                this.position.district = districtData.name || districtRef;
              }
            }
          } catch (err) {
            console.error("Error loading facility hierarchy:", err);
          }
        }

        // Position Basic → designation (via a nested Basic) + department
        const posRef = role.extension?.find(
          (e) => e.url === POSITION_EXT.POSITION,
        )?.valueReference;
        if (posRef?.reference) {
          try {
            const posId = posRef.reference.split("/")[1];
            const posRes = await fetch(`/fhir/Basic/${posId}`);
            const posData = await posRes.json();

            const desigRef = posData.extension?.find(
              (e) => e.url === POSITION_EXT.DESIGNATION,
            )?.valueReference;
            if (desigRef?.reference) {
              try {
                const dId = desigRef.reference.split("/")[1];
                const dRes = await fetch(`/fhir/Basic/${dId}`);
                const dData = await dRes.json();
                this.position.designation =
                  dData.extension?.find(
                    (e) => e.url === POSITION_EXT.POS_NAME,
                  )?.valueString ||
                  desigRef.display ||
                  "";
              } catch (_) {
                this.position.designation = desigRef.display || "";
              }
            }

            const deptCoding = posData.extension?.find(
              (e) => e.url === POSITION_EXT.DEPARTMENT,
            )?.valueCoding;
            this.position.department =
              deptCoding?.display || deptCoding?.code || "";
          } catch (err) {
            console.error("Error loading position:", err);
          }
        }
      } catch (error) {
        console.error("Error loading staff position:", error);
      }
    },

    async submitReview() {
      this.formSubmitted = true;
      if (
        !this.form.status ||
        !this.form.comments ||
        !this.form.comments.trim()
      ) {
        this.showSnackbar(
          "Please select a decision and add comments.",
          "error",
        );
        return;
      }

      this.saving = true;
      try {
        this.fhir = {
          reviewDecision: this.form.status,
          comments: this.form.comments,
          date: this.form.date,
        };
        this.$route.query.practitioner = this.refId(
          this.staffPractitionerRef,
        );
        this.$route.query.request = this.requestId;
        this.afterSaveMessage = `${this.stageConfig.label} review submitted successfully!`;
        await this.processFHIR();
        this.showSnackbar(this.afterSaveMessage, "success");
        setTimeout(() => this.goBack(), 300);
      } catch (error) {
        console.error("submitReview error:", error);
        this.showSnackbar(
          "Failed to submit review. Please try again.",
          "error",
        );
      } finally {
        this.saving = false;
      }
    },

    goBack() {
      if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    isCurrentStage(stage) {
      return stage.expectedStatus === this.request.status;
    },
  },

  async mounted() {
    await this.$nextTick();

    // Wait for generalMixin to finish loading loggedInStaff
    await new Promise((resolve) => {
      if (!this.loadingUserData) {
        resolve();
        return;
      }
      const unwatch = this.$watch("loadingUserData", (newValue) => {
        if (!newValue) {
          unwatch();
          resolve();
        }
      });
      setTimeout(() => {
        unwatch();
        resolve();
      }, 15000);
    });

    this.requestId = this.queries?.request;
    if (!this.requestId) {
      this.error = "No early retirement request specified.";
      this.loading = false;
      return;
    }

    try {
      await this.loadRequest();
      await Promise.all([
        this.loadPractitioner(),
        this.loadReviews(),
        this.loadStaffPosition(),
      ]);
    } catch (error) {
      console.error("Error loading early retirement request:", error);
      this.error =
        error.message || "Failed to load this early retirement request";
    } finally {
      this.loading = false;
    }
  },
};
